INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66154539', 66154539, 'analyze_legacy', 'Kementerian Kelautan Dan Perikanan', 'central', 'PELABUHAN PERIKANAN NUSANTARA PENGAMBENGAN', 'Outsourcing Jasa Tenaga kebersihan', 'Jasa Lainnya', 'E-Purchasing', 'Bali, Jembrana (Kab.)', 769148000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, Paket, @ 875257000 )', '1. Outsourcing Jasa Tenaga kebersihan (15 orang) ( 1, Paket, @ 875257000 );', '1. Ruang Lingkup Pekerjaan Pembersihan Area Dalam (Indoor): Lantai (sapu/pel), pembersihan meja kerja, kursi, lemari, pembersihan kaca jendela bagian dalam, dan plafon dari sarang laba-laba. Pembersihan Fasilitas Umum: Pembersihan toilet/kamar mandi secara berkala (minimal 2x sehari), mushola, dan area pantry. Area Luar (Outdoor): Pembersihan teras, halaman parkir, dan selokan di lingkungan kantor. Pengelolaan Sampah: Pengumpulan sampah dari ruangan ke Tempat Pembuangan Sementara (TPS). 2. Standar Tenaga Kerja Kualifikasi: Pria/Wanita, usia produktif (misal 18-40 tahun), berkelakuan baik, dan sehat jasmani/rohani. Seragam: Wajib mengenakan seragam kerja yang bersih dan rapi serta tanda pengenal (ID Card). Etika: Sopan, jujur, dan menjaga kerahasiaan dokumen di area kantor. 3. Alat dan Bahan Pembersih (Chemicals) Peralatan: Sapu, alat pel (mop), penyedot debu (vacuum cleaner), pembersih kaca (wiper), tempat sampah, dan kantong plastik sampah. Bahan Kimia: Cairan pembersih lantai (disinfektan), sabun cuci tangan, pembersih kaca, pengharum ruangan, dan pembersih porselen/keramik toilet. 4. Jadwal Kerja Harian: Pembersihan rutin sebelum jam kantor dimulai (pukul 07.00) dan selama jam kerja berlangsung. Mingguan: Pembersihan besar (General Cleaning) seperti penyikatan lantai selasar, pembersihan kaca luar, atau pemotongan rumput.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2554641);
