INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66118407', 66118407, 'analyze_legacy', 'Kementerian Agama', 'central', 'KANWIL KEMENTERIAN AGAMA PROP MALUKU UTARA 626377', 'Perencanaan Pembangunan KUA Kec. Tobelo Utara', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Maluku Utara, Ternate (Kota)', 90000000, 'March 2026', 'APBN - SBSN (T)', 0, 1, '1 paket @90.000.000', 'Persiapan dan pengumpulan data (survey lokasi, pengukuran, dan identifikasi kebutuhan ruang). Penyusunan konsep perencanaan (pra-desain dan desain arsitektur). Penyusunan gambar teknis lengkap (arsitektur, struktur, mekanikal, elektrikal, dan plumbing). Perhitungan struktur dan utilitas bangunan. Penyusunan Rencana Anggaran Biaya (RAB) dan Bill of Quantity (BOQ). Penyusunan Rencana Kerja dan Syarat-syarat (RKS). Penyusunan dokumen pendukung lainnya yang diperlukan untuk proses pengadaan dan pelaksanaan konstruksi.', 'Perencanaan mengacu pada standar teknis bangunan gedung pemerintah dan ketentuan tata ruang setempat. Desain bangunan memperhatikan fungsi pelayanan publik KUA, aspek keamanan, kenyamanan, aksesibilitas, dan efisiensi ruang. Gambar teknis disusun secara detail dan terkoordinasi antar disiplin (arsitektur, struktur, MEP). Perhitungan struktur mengacu pada standar nasional yang berlaku. Penyusunan RAB menggunakan analisa harga satuan pekerjaan sesuai standar terbaru pemerintah daerah setempat. Dokumen disusun dalam bentuk hardcopy dan softcopy (format PDF dan editable). Konsultan perencana wajib memiliki tenaga ahli sesuai bidangnya (arsitek, insinyur sipil/struktur, dan tenaga MEP) yang dibuktikan dengan kualifikasi dan sertifikat keahlian yang masih berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2554847);
