INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66159564', 66159564, 'analyze_legacy', 'Kementerian Dalam Negeri', 'central', 'DIREKTORAT JENDERAL KEPENDUDUKAN DAN PENCATATAN SIPIL', 'Tenaga Ahli Hukum', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 840000000, 'March 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '42 OB', '1. Melaksanakan reviu, analisa permasalahan, pemahaman isu penegakan hukum dan rekomendasi hukum di bidang pemanfaatan data kependudukan, pendaftaran penduduk, pencatatan sipil, Sistem Informasi Administrasi Kependudukan, perlindungan data pribadi dan aparatur penyelenggara administrasi kependudukan di daerah. 2. Menyusun dan menyempurnakan sistem kerja, tata kelola, komunikasi dan pelaporan yang efektif, agar siap dan responsif dalam membantu analisa kasus hukum; 3. Menyusun pedoman/acuan dalam memberikan advokasi dan konsultasi hukum terkait permasalahan hukum bidang administrasi kependudukan berdasarkan tipe kasus; 4. Memastikan bentuk dan isi penyelesaian kasus hukum sesuai dengan asas-asas hukum; 5. Memberikan masukan, opsi-opsi pemecahan masalah, dan membantu untuk menyelesaikan permasalahan dan kasus-kasus hukum di bidang administrasi kependudukan dalam lingkup permasalahan dan kasus hukum yang ada di lintas Provinsi/Kabupaten/Kota dan tingkatan kasus lainnya sesuai penugasan yang diberikan; 6. Melakukan konsultasi, advokasi dan pendampingan hukum di lingkungan Ditjen Dukcapil Kemendagri dan Dinas Dukcapil sesuai dengan Peraturan Perundang-Undangan yang berlaku di Indonesia; 7. Melaksanakan tugas lainnya dalam konteks no 3-5 di atas berdasarkan arahan pimpinan dalam lingkup Direktorat Jenderal Kependudukan dan Pencatatan Sipil;', '1. Memiliki latar belakang Pendidikan minimal Magister Hukum di bidang hukum. 2. Minimal 4 tahun pengalaman dalam Bidang Penegakan Hukum, Kebijakan Hukum atau Lembaga Hukum dan menangani kasus hukum; 3. Memiliki keterampilan dalam analisis kebijakan hukum, termasuk metode analisis; 4. Mampu melakukan reviu regulasi/peraturan perundang-undangan; 5. Memahami sistem peradilan Indonesia, serta proses penegakan hukum; 6. Sertifikasi dalam bidang Hukum akan menjadi nilai tambah.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2555094);
